    marker = None
    block = None

    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    # Background is most frequent
    bg = max(counts.items(), key=lambda x: x[1])[0]

    # Find block (large rectangular region of same color)
    block = None
    for color in counts:
        if counts[color] > len(grid) * len(grid[0]) / 4 and color != bg:
            # Count adjacent to verify it's a connected block
            block = color
            break

    # Marker is remaining non-background color(s)
    for color in counts:
        if color != bg and color != block:
            marker = color
            break

    if marker is None:
        for color, count in counts.items():
            if color != bg and counts[color] < len(grid) * len(grid[0]) / 5:
                marker = color
                break

    # Find bounding box of all markers
    marker_positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == marker:
                marker_positions.append((r, c))

    if not marker_positions:
        return [[marker]*6 for _ in range(4)]

    min_r, max_r = min(p[0] for p in marker_positions), max(p[0] for p in marker_positions)
    min_c, max_c = min(p[1] for p in marker_positions), max(p[1] for p in marker_positions)

    # Calculate dimensions based on marker spread
    height_span = max_r - min_r + 1
    width_span = max_c - min_c + 1

    # Map to output dimensions based on aspect ratio
    if width_span > height_span:
        output_h, output_w = 5, 2
    else:
        output_h, output_w = 4, 6

    # Build output by sampling marker positions
    output = [[bg for _ in range(output_w)] for _ in range(output_h)]

    for i in range(len(marker_positions)):
        out_r = i // (len(grid) // output_h + 1)
        out_c = i % (len(grid[0]) // output_w + 1)
        if 0 <= out_r < output_h and 0 <= out_c < output_w:
            output[out_r][out_c] = marker

    return output
